-- Initial PostgreSQL schema. Do not drop pre-existing user data.
CREATE TABLE IF NOT EXISTS "User" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "name" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "Post" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "content" TEXT, "published" BOOLEAN NOT NULL DEFAULT false, "authorId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Post_pkey" PRIMARY KEY ("id"));
CREATE TABLE IF NOT EXISTS "RaceRecord" ("id" SERIAL NOT NULL, "racerName" TEXT NOT NULL DEFAULT 'RACER', "laps" INTEGER NOT NULL, "timeMs" INTEGER NOT NULL, "bestLapMs" INTEGER NOT NULL, "topSpeedKmh" INTEGER NOT NULL, "driftScore" INTEGER NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "RaceRecord_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "User_email_key" ON "User"("email");
